function event_slay(e)
	if e.other:IsClient() or e.other:IsPet() then -- not sure why this is necessary, but otherwise will occasionally spawn adds when an event mob dies
		local x,y,z,h = e.other:GetX(), e.other:GetY(), e.other:GetZ(), e.other:GetHeading();
		eq.spawn2(eq.ChooseRandom(292043,292044,292045,292046,292047,292048,292049,292050),0,0,x,y,z,h); -- NPC(s): #a_coercing_spirit (292043), #a_malevolent_spirit (292044), #a_slighted_spirit (292045), #a_spiteful_spirit (292046), #a_vengeful_spirit (292047), #a_vindictive_spirit (292048), #an_avenging_spirit (292049), #an_infuriated_spirit (292050)
	end
end

function event_say(e)
	if(e.message:findi("lights glory")) then
		e.self:Say("The Light's Glory? Yes I know of that ship. I have seen it many times. Many ships come through here on their way to Erudin. I hear many stories, many tales of the ocean. [Bad news] is all I have for you this day however.");
	elseif(e.message:findi("bad news")) then
		e.self:Say("Your ship left our dock almost a week ago. I watched the ocean that night, as I do every night. Your ship was attacked as it left the dock. There was a big battle. I saw many Erudites thrown overboard. The ship was captured and taken away with the pirate vessel. What became of your ship, I do not know. You could perhaps swim out and take a look for any clues.");
	end
end

function event_combat(e)
  if e.joined then
    e.self:Say(string.format("Time to die %s!",e.other:GetCleanName()));
  end
end

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say(string.format("Hello. %s.  My name is Hezlan Nur and I am a member of the Qeynos Guard. serving the will of Antonius Bayle.  Anything or anyone trying to get into Qeynos has to go through me. first.  Heh!  I sure love it when those dirty Sabertooths try. though!  Nothing is as gratifying as the death wail of a gnoll.",e.other:GetName()));
	end
end

function event_signal(e)
		e.self:Say("It isn't safe to be asking that kind of question. I just mind my business and do my job. You would, too, if you knew what was good for you.");
end

-- items: 13118, 13994, 13836, 17918
function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Greetings, fellow traveler! I gotta tell ya. I love this town. Especially Crow's. Although the crowd seems a bit shadier than other places of the sort.");
	elseif(e.message:findi("testament of vanear")) then
		e.self:Say("So you have heard that good old Moodoro has knowledge of the Testament of Vanear. I care little for that book. Of course I have it!! If you want it, I will sell it to you for two gold pieces.");
	elseif(e.message:findi("ran")) then
		e.self:Say("Ran Flamespinner is a librarian in Highpass Hold.");
	elseif(e.message:findi("page 34")) then
		e.self:Say("So, you know I have page 34. Pretty smart of me to tear the most important page out before someone else tried, eh? If you really want it, then sit down and deal in. Ante is 4 gold. I will give you one card. If it is a jester, then I will give you the page. Let's do it.");
	elseif(e.message:findi("tonic")) then
		e.self:Say("I need some of Erud's tonic water. There is a merchant in Erudin who sells it.");
	end
end

function event_waypoint_arrive(e)
	if(e.wp == 6) then
		e.self:Say("<urp>.. I don't feel so well.");
		eq.signal(2091,1,1); -- NPC: Flynn_Merrington
	elseif(e.wp == 14) then
		eq.set_anim(2040,1);
	end
end

function event_signal(e)
	if(e.wp == 14) then
		e.self:Say("Ooooh.. Bllaughhh.. Ooh.. I need some tonic.");
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 13118})) then
		e.self:Say("Oh thank the maker you have returned. Here is a little something in return");
		e.other:Ding();
		e.other:Faction(233,20,0); -- Faction: Crimson Hands
		e.other:Faction(266,20,0); -- Faction: High Council of Erudin
		e.other:Faction(265,-20,0); -- Faction: Heretics
		e.other:Faction(267,20,0); -- Faction: High Guard of Erudin
		e.other:AddEXP(200);
		e.other:GiveCash(5,0,0,0);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13994})) then
		e.self:Say("Lucky you. We were hoping to really clean you out. Here you go. Take the page. Even together, the book is nothing more than fiction.");
		e.other:Ding();
		e.other:SummonItem(13836); -- Item: Page 34 of a Book
	elseif(item_lib.check_turn_in(e.trade, {gold = 4})) then
		local random_card = eq.ChooseRandom(13994,13993,13992,13995);
		e.other:Ding();
		e.self:Say("Well, what do you have?!!");
		e.other:SummonItem(random_card);
	elseif(item_lib.check_turn_in(e.trade, {gold = 2})) then
		e.self:Say("HA!! I hope you enjoy the book. It is missing pages 30 and 34. It is nothing more than garbage without them. A rogue ripped them from their bindings and sold them to [Ran].");
		e.other:Ding();
		e.other:SummonItem(17918); -- Item: Testament of Vanear
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

function event_death_complete(e)
	e.self:Emote(string.format("'s corpse says 'I'll get you back %s!'",e.other:GetCleanName()));
end

function event_spawn(e)
	e.self:SetRace(69);
	e.self:SetTexture(1);
	e.self:ChangeSize(4);
end

