function event_scale_calc(e)
	local Total		= 0;
	local Helm		= tonumber(e.owner:HasItemEquippedByID(72326));
	local Chest		= tonumber(e.owner:HasItemEquippedByID(72328));
	local Arms		= tonumber(e.owner:HasItemEquippedByID(72338));
	local Legs		= tonumber(e.owner:HasItemEquippedByID(72330));
	local Gloves	= tonumber(e.owner:HasItemEquippedByID(72320));
	local Feet		= tonumber(e.owner:HasItemEquippedByID(72322));
	local Wrist		= tonumber(e.owner:HasItemEquippedByID(72336));
	Total		= Helm + Chest + Arms + Legs + Gloves + Feet + Wrist;

	if Total < 0 then
		e.self:SetScale(0);
	elseif Total > 7 then
		e.self:SetScale(1);
	else
		e.self:SetScale(Total/7);
	end
end

